//! Pipeline for the affine resample pass.
//!
//! [`ResamplePipeline`] owns the `wgpu::RenderPipeline` that
//! [`super::apply_resample`] draws with, built for one target format.
//!
//! ## Bind-group layout (group 0)
//!
//! Generated by `wgsl_bindgen` from `resample.wgsl`; see `super::generated`.
//!
//! | Binding | Stage | Type              | Content                        |
//! |---------|-------|-------------------|--------------------------------|
//! | 0       | FS    | Uniform buffer    | `ResampleUniforms` (48 bytes)  |
//! | 1       | FS    | 2D float texture  | Source (premultiplied RGBA)    |
//! | 2       | FS    | Filtering sampler | Nearest or linear, clamped     |

use super::generated::resample;

/// The generated `ResampleUniforms` is the 48 bytes `resample.wgsl` declares.
const _RESAMPLE_UNIFORMS_LAYOUT_CHECK: () = {
    assert!(std::mem::size_of::<resample::ResampleUniforms>() == 48);
    assert!(std::mem::offset_of!(resample::ResampleUniforms, map_x) == 0);
    assert!(std::mem::offset_of!(resample::ResampleUniforms, map_y) == 16);
    assert!(std::mem::offset_of!(resample::ResampleUniforms, source_size) == 32);
};

/// Render pipeline for the resample pass.
///
/// The shader writes the resampled premultiplied texel as it is: the blend
/// state is `REPLACE`.
pub(crate) struct ResamplePipeline {
    pub(crate) pipeline: wgpu::RenderPipeline,
}

impl ResamplePipeline {
    /// Build the pipeline for `surface_format`.
    pub(crate) fn new(device: &wgpu::Device, surface_format: wgpu::TextureFormat) -> Self {
        let bind_group_layout = resample::WgpuBindGroup0::get_bind_group_layout(device);
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("Resample Pipeline Layout"),
            bind_group_layouts: &[Some(&bind_group_layout)],
            immediate_size: 0,
        });
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("Resample Shader"),
            source: wgpu::ShaderSource::Wgsl(
                include_str!("../shaders/effects/resample.wgsl").into(),
            ),
        });
        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("Resample Pipeline"),
            layout: Some(&pipeline_layout),
            vertex: wgpu::VertexState {
                module: &shader,
                entry_point: Some("vs_main"),
                // The vertex stage makes a full-target quad from the vertex index.
                buffers: &[],
                compilation_options: wgpu::PipelineCompilationOptions::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &shader,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    blend: Some(wgpu::BlendState::REPLACE),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: wgpu::PipelineCompilationOptions::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                strip_index_format: None,
                front_face: wgpu::FrontFace::Ccw,
                cull_mode: None,
                polygon_mode: wgpu::PolygonMode::Fill,
                unclipped_depth: false,
                conservative: false,
            },
            depth_stencil: None,
            multisample: wgpu::MultisampleState {
                count: 1,
                mask: !0,
                alpha_to_coverage_enabled: false,
            },
            multiview_mask: None,
            cache: None,
        });
        Self { pipeline }
    }
}
